package co.com.empresa.infrastructure.controller.type;import co.com.empresa.application.type.TypeRequestDto;import co.com.empresa.application.type.TypeResponseDto;import co.com.empresa.application.type.TypeUseCase;import co.com.empresa.commons.helper.ApiResponseBuilder;import co.com.empresa.commons.services.i18.MessageService;import co.com.empresa.infrastructure.type.TypeRestController;import org.junit.jupiter.api.BeforeEach;import org.junit.jupiter.api.DisplayName;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.InjectMocks;import org.mockito.Mock;import org.mockito.junit.jupiter.MockitoExtension;import java.time.LocalDateTime;import static org.mockito.ArgumentMatchers.any;import static org.mockito.Mockito.*;@ExtendWith(MockitoExtension.class)class TypeRestControllerTest {    @Mock    private TypeUseCase typeUseCase;    @Mock    private MessageService messageService;    @Mock    private ApiResponseBuilder responseBuilder;    @InjectMocks    private TypeRestController typeRestController;    private TypeRequestDto requestDto;    private TypeResponseDto responseDto;    @BeforeEach    void setUp() {        requestDto = new TypeRequestDto(null, 1L, "Test Name", "TEST-001", "Test Description", true);        responseDto = new TypeResponseDto(1L, 1L, "Test Name", "TEST-001", "Test Description", true, "system", LocalDateTime.now(), null, null);    }    @Test    @DisplayName("create: Should return created type")    void create_ReturnsCreated() {        when(typeUseCase.create(any())).thenReturn(responseDto);        when(messageService.getMessage(anyString())).thenReturn("Success");        when(responseBuilder.success(any(), anyString())).thenReturn(null);        var result = typeRestController.create(requestDto);        verify(typeUseCase).create(any());    }    @Test    @DisplayName("getById: Should return type when exists")    void getById_ReturnsType() {        Long id = 1L;        when(typeUseCase.getById(id)).thenReturn(responseDto);        when(messageService.getMessage(anyString())).thenReturn("Success");        when(responseBuilder.success(any(), anyString())).thenReturn(null);        var result = typeRestController.getById(id);        verify(typeUseCase).getById(id);    }}